    for(int fault=0;fault<4;++fault){CommonStore rejected(seed,catalog);auto move=MoveIntegrationLot{"old.store","new.store","lot:public",4,old,next};if(fault==0)move.expected_quantity=3;if(fault==1)rejected.state().inventories.find("old.store")->lots[0].reserved_by="action:held";if(fault==2)rejected.state().inventories.find("new.store")->capacity=7;if(fault==3)move.lot_id="lot:private";assert(!rejected.apply_resources({{move},{}}).ok);assert(rejected.inventory("old.store")->lots.size()==2&&rejected.inventory("new.store")->lots.empty());}
